const id='wfrp4e-complete-counts-pl',api=game.modules.get(id).api,a=canvas.tokens.controlled[0]?.actor||game.user.character;
try{if(!a?.isOwner||!a.getFlag(id,'vampire'))throw Error('Wybierz własnego wampira.');
const amount=(title,value)=>foundry.applications.api.DialogV2.prompt({window:{title},content:`<input name=amount type=number min=1 value=${value}>`,ok:{label:'Zastosuj',callback:(_e,b)=>Number(b.form.elements.amount.value)},rejectClose:false});
const use=async(kind,predicate=()=>true)=>{const items=a.items.filter(i=>i.flags[id]?.kind===kind&&predicate(i.flags[id]?.en||i.name));if(!items.length)throw Error('Brak odpowiedniej mocy.');const key=await foundry.applications.api.DialogV2.prompt({window:{title:'Wybierz moc'},content:'<select name=item>'+items.map(i=>`<option value=${i.id}>${foundry.utils.escapeHTML(i.name)}</option>`).join('')+'</select>',ok:{label:'Użyj',callback:(_e,b)=>b.form.elements.item.value},rejectClose:false});if(key)await api.activate(a.items.get(key));};
const target=[...game.user.targets][0]?.actor;if(!target)throw Error('Zaznacz cel Blood Kiss.');const mode=await foundry.applications.api.DialogV2.wait({window:{title:'Blood Kiss'},buttons:[{action:'Willing',label:'Willing — dobrowolnie'},{action:'Forced',label:'Forced — przymusowo'}],rejectClose:false});if(mode)await api.bloodKiss(a,target,{mode});
}catch(e){ui.notifications.error(e.message);}

